let Account = parse_json(base64_decode_tostring('{AccountJson5:base64}'));
let Inventory = parse_json(base64_decode_tostring('{DeploymentJson5:base64}'));
let SelectedAccountCount = array_length(split(strcat_array(dynamic([{Foundry}]), ','), ','));
