    | where isempty(CorrelationId)
    | extend Host = tolower(tostring(parse_url(BackendUrl).Host)),
        BackendPath = tostring(parse_url(BackendUrl).Path)
    | extend BackendDeployment = tolower(url_decode(extract(@"(?i)/deployments/([^/?]+)", 1, BackendPath)))
    | join kind=leftouter AccountHosts on Host
    | where isnotempty(AccountResourceId) or isnotempty(BackendDeployment)
        or tolower(BackendPath) startswith '/openai/' or isempty(Host)
    | project TimeGenerated, UnsafeAccount = tostring(AccountResourceId), UnsafeDeployment = BackendDeployment
);
let OrphanLlm = materialize(
    LlmByCall
    | where FirstSeen >= AlignedStart and FirstSeen < AlignedEnd
    | join kind=leftanti (GatewayCalls | project ApimResourceId, CorrelationId)
        on ApimResourceId, CorrelationId
);
let GatewayInstanceCount = toscalar(GatewayCalls | distinct ApimResourceId | count);
let Calls = materialize(
    GatewayCalls
    | join kind=leftouter hint.shufflekey=CorrelationId LlmByCall on ApimResourceId, CorrelationId
    | extend HasLlm = coalesce(HasLlm, false), UsageKnown = coalesce(UsageKnown, false)
    | extend LlmCandidate = tolower(iff(isnotempty(ClientDeployment) and not(ClientDeployment startswith '<'),
        ClientDeployment, coalesce(ClientModel, '')))
    | join kind=leftouter (Deployments | project AccountResourceId, LlmCandidate = DeploymentName, LlmDeployment = Deployment)
        on AccountResourceId, LlmCandidate
    | where HasLlm or isnotempty(BackendDeployment)
        or (isnotempty(AccountResourceId) and tolower(BackendPath) startswith '/openai/')
    | extend ClientDeployment = iff(isempty(ClientDeployment), '<unobserved deployment>', ClientDeployment)
    | extend BackendMatched = isnotempty(AccountResourceId) and isnotempty(BackendDeployment)
    | extend LlmMatched = not(BackendMatched) and isnotempty(LlmDeployment)
    | extend Deployment = case(BackendMatched, strcat(AccountResourceId, '/deployments/', BackendDeployment),
        LlmMatched, LlmDeployment,
        strcat('<unmapped>/deployments/', coalesce(BackendDeployment, ClientDeployment)))
    | extend RawSubscription = iff(isempty(ApimSubscriptionId), '<no subscription>', tostring(ApimSubscriptionId))
    | project TimeGenerated, ApimResourceId, CorrelationId, AccountResourceId,
        TargetDeployment = case(LlmMatched, LlmCandidate, isnotempty(BackendDeployment), BackendDeployment,
            not(ClientDeployment startswith '<'), ClientDeployment, ''),
        BackendMatched = BackendMatched or LlmMatched,
        SubscriptionId = iff(GatewayInstanceCount > 1,
            strcat(tostring(split(ApimResourceId, '/')[-1]), ' / ', RawSubscription), RawSubscription),
        Deployment, HasLlm, UsageKnown,
        Tokens = iff(UsageKnown, TotalTokens, long(0)),
        Weighted = iff(UsageKnown,
            iff(OutputWeight == 1.0, todouble(TotalTokens), todouble(PromptTokens) + OutputWeight * todouble(CompletionTokens)),
            0.0)
);
let TokenlessTargets = materialize(
    Calls
    | where BackendMatched
    | summarize Total = count(), Missing = countif(not(UsageKnown))
        by Bucket = bin(TimeGenerated, Grain), UnsafeAccount = AccountResourceId, UnsafeDeployment = TargetDeployment
    | where Missing > 0.05 * Total
);
let UnsafeTraffic = materialize(
    union
        (Calls
         | where not(BackendMatched)
         | project TimeGenerated, UnsafeAccount = AccountResourceId, UnsafeDeployment = TargetDeployment),
        (TokenlessTargets | project TimeGenerated = Bucket, UnsafeAccount, UnsafeDeployment),
        UncorrelatedGateway,
        (union
             (OrphanLlm | project TimeGenerated = FirstSeen),
             (UncorrelatedLlm | project TimeGenerated)
         | mv-expand Offset = dynamic([-1, 0, 1]) to typeof(long)
         | extend TimeGenerated = TimeGenerated + Offset * 1h
         | where TimeGenerated >= AlignedStart and TimeGenerated < AlignedEnd
         | project TimeGenerated, UnsafeAccount = '', UnsafeDeployment = '')
    | summarize by Bucket = bin(TimeGenerated, Grain), UnsafeAccount, UnsafeDeployment
);
let BlockedTargets = materialize(
    Deployments
    | extend JoinKey = 1
    | join kind=inner (UnsafeTraffic | extend JoinKey = 1) on JoinKey
    | where (isempty(UnsafeAccount) or UnsafeAccount == AccountResourceId)
        and (isempty(UnsafeDeployment) or UnsafeDeployment == DeploymentName)
    | project Deployment, Bucket
    | distinct Deployment, Bucket
);
let UtilRaw = materialize(
    SourcesFull
    | project AccountResourceId, Series = Metric.value[0].timeseries
    | mv-expand Series
    | mv-expand Dimension = Series.metadatavalues
    | where tostring(Dimension.name.value) =~ 'ModelDeploymentName'
    | project AccountResourceId, DeploymentName = tolower(tostring(Dimension.value)), Points = Series.data
    | join kind=inner Deployments on AccountResourceId, DeploymentName
    | project AccountResourceId, Deployment, Ptu, Created, Modified, Points
    | mv-expand Points
    | extend TimeGenerated = todatetime(Points.timeStamp), UtilAvgPct = todouble(Points.average),
        UtilMaxPct = coalesce(todouble(Points.maximum), todouble(Points.average))
    | where TimeGenerated >= AlignedStart and TimeGenerated < AlignedEnd and isnotnull(UtilAvgPct)
    | where TimeGenerated + 1h > Created and TimeGenerated >= Modified and SourcesComplete
    | project TimeGenerated, AccountResourceId, Deployment, Ptu, UtilAvgPct, UtilMaxPct
);
let ExpectedSamples = materialize(
    Deployments
    | where AlignedEnd > AlignedStart
    | mv-expand TimeGenerated = range(AlignedStart, AlignedEnd - 1h, 1h) to typeof(datetime)
    | where TimeGenerated + 1h > Created
    | project AccountResourceId, Deployment, TimeGenerated
);
let MissingSamples = materialize(
    ExpectedSamples
    | join kind=leftanti (UtilRaw | distinct AccountResourceId, Deployment, TimeGenerated)
        on AccountResourceId, Deployment, TimeGenerated
);
let DuplicateSamples = materialize(
    UtilRaw
    | summarize N = count() by AccountResourceId, Deployment, TimeGenerated
    | where N > 1
);
let IncompleteBuckets = materialize(
    union MissingSamples, (DuplicateSamples | project AccountResourceId, Deployment, TimeGenerated)
    | summarize by Deployment, Bucket = bin(TimeGenerated, Grain)
);
let AllUtil = materialize(
    UtilRaw
    | extend Bucket = bin(TimeGenerated, Grain)
    | join kind=leftanti IncompleteBuckets on Deployment, Bucket
    | join kind=leftouter (BlockedTargets | extend Blocked = long(1)) on Deployment, Bucket
    | extend Blocked = coalesce(Blocked, long(0))
    | summarize PtuTotal = sum(Ptu), InUse = sum(Ptu * UtilAvgPct / 100.0),
        UtilMaxPct = max(UtilMaxPct), Blocked = max(Blocked) by TimeGenerated, Deployment
    | summarize PtuTotal = avg(PtuTotal), InUse = avg(InUse), UtilMaxPct = max(UtilMaxPct),
        Blocked = max(Blocked) by Bucket = bin(TimeGenerated, Grain), Deployment
);
let Util = AllUtil | where Blocked == 0;
let SharedDeploymentCount = toscalar(Deployments | summarize Accounts = dcount(AccountResourceId) by DeploymentName
    | where Accounts > 1 | count);
let ModifiedInRange = toscalar(Deployments | where Modified > AlignedStart and Created < AlignedEnd | count);
let Tok = materialize(
    Calls
    | summarize Calls = count(), Tokens = sum(Tokens), Weighted = sum(Weighted), MissingUsage = countif(not(UsageKnown))
        by Bucket = bin(TimeGenerated, Grain), Deployment, SubscriptionId
);
let TokTot = Tok | summarize WeightedAll = sum(Weighted) by Bucket, Deployment;
let Rows = materialize(
    union
    (
        Tok
        | join kind=inner TokTot on Bucket, Deployment
        | join kind=leftouter Util on Bucket, Deployment
        | project Bucket, Deployment, SubscriptionId, Calls, Tokens, Weighted, MissingUsage,
            Measured = isnotnull(InUse),
            PtuInUse = iff(isnotnull(InUse) and WeightedAll > 0, Weighted / WeightedAll * InUse, real(null))
    ),
    (
        Util
        | join kind=leftanti (TokTot | where WeightedAll > 0) on Bucket, Deployment
        | where InUse > 0
        | project Bucket, Deployment, SubscriptionId = '<unattributed>', Calls = long(0), Tokens = long(0),
            Weighted = 0.0, MissingUsage = long(0), Measured = true, PtuInUse = InUse
    )
);
let MeasuredBuckets = materialize(Util | summarize MeasuredBuckets = dcount(Bucket) by Deployment);
let DeploymentWeighted = materialize(Rows | summarize DeploymentWeighted = sum(Weighted) by Deployment);
let Detail = materialize(
    Rows
    | summarize Calls = sum(Calls), Tokens = sum(Tokens), Weighted = sum(Weighted), MissingUsage = sum(MissingUsage),
        PtuSum = sum(PtuInUse), PeakPtu = max(PtuInUse), UnmeasuredTokens = sumif(Tokens, not(Measured))
        by SubscriptionId, Deployment
    | join kind=leftouter MeasuredBuckets on Deployment
    | join kind=leftouter DeploymentWeighted on Deployment
    | project SubscriptionId, Deployment, Calls, Tokens, Weighted, MissingUsage, DeploymentWeighted, PeakPtu, UnmeasuredTokens,
        AvgPtuInUse = iff(MeasuredBuckets > 0, PtuSum / MeasuredBuckets, real(null))
);
let ChartGrain = Grain * max_of(1.0, ceiling(((AlignedEnd - AlignedStart) / Grain) / 200.0));
let GatewayN = toscalar(GatewayCalls | count);
let LlmN = toscalar(Calls | where HasLlm | count);
let UsageN = toscalar(Calls | where UsageKnown | count);
let NamedN = toscalar(Calls | where HasLlm and BackendMatched | count);
let UtilN = toscalar(UtilRaw | count);
let LatestUtil = toscalar(UtilRaw | summarize max(TimeGenerated));
let NoUtilDeployments = toscalar(Calls | where not(Deployment startswith '<') | summarize by Deployment
    | join kind=leftanti (UtilRaw | summarize by Deployment) on Deployment | count);
union
(print Step = 8, Check = 'Deployment inventory complete',
    Result = case(not(InventoryValid), 'No valid inventory response', InventoryTruncated, 'Additional pages returned',
        InvalidInventory > 0, 'Invalid deployment capacity or name', 'Complete'),
    Status = case(not(InventoryValid), 'Missing', InventoryTruncated or InvalidInventory > 0, 'Check', 'OK'),
    Fix = 'Check account access and inventory. This preview cannot safely use a paged or invalid inventory.'),
(print Step = 9, Check = 'Metric series limit',
    Result = iff(MetricsValid, tostring(MetricSeriesCount), 'No valid metric response'),
    Status = case(not(MetricsValid), 'Missing', MetricSeriesLimit, 'Check', 'OK'),
    Fix = 'Check metric access. The preview cannot safely use a response at the 200-series limit.'),
(print Step = 10, Check = 'APIM usage without a safe PTU allocation',
    Result = tostring(toscalar(Rows | where not(Measured) and Tokens > 0 | count)),
    Status = iff(toscalar(Rows | where not(Measured) and Tokens > 0 | count) > 0, 'Check', 'OK'),
    Fix = 'Some token usage cannot be assigned PTU because metrics or APIM traffic are incomplete.'),
(print Step = 11, Check = 'Deployment creation times available',
    Result = tostring(MissingCreation),
    Status = iff(MissingCreation > 0, 'Check', 'OK'),
    Fix = 'PTU estimates are suppressed when a deployment creation time is unavailable.'),
(print Step = 12, Check = 'Incomplete deployment time buckets',
    Result = tostring(toscalar(IncompleteBuckets | count)),
    Status = iff(toscalar(IncompleteBuckets | count) > 0, 'Check', 'OK'),
    Fix = 'A missing or duplicate hourly sample prevents PTU allocation for that deployment and time bucket.'),
(print Step = 13, Check = 'Deployment names shared across accounts',
    Result = tostring(SharedDeploymentCount),
    Status = 'OK',
    Fix = 'APIM backend URLs distinguish same-named deployments when each backend is identifiable.'),
(print Step = 14, Check = 'Deployment changes or creation in selected range',
    Result = tostring(ModifiedInRange),
    Status = iff(ModifiedInRange > 0, 'Check', 'OK'),
    Fix = 'Buckets before or overlapping the reported change start are omitted. Completion time and previous capacity are not established.'),
(print Step = 15, Check = 'Deployment capacity and modification metadata',
    Result = strcat('Missing modification times: ', tostring(MissingModification),
        '; unknown or changing capacity: ', tostring(UnstableDeployments)),
    Status = iff(MissingModification > 0 or UnstableDeployments > 0, 'Check', 'OK'),
    Fix = 'PTU estimates are suppressed until every PTU deployment has a modification time and stable active capacity.'),
(print Step = 16, Check = 'Selected model resources',
    Result = strcat(tostring(SelectedAccountCount), ' selected; preview limit is 5'),
    Status = iff(SelectedAccountCount >= 1 and SelectedAccountCount <= 5, 'OK', 'Check'),
    Fix = 'Select no more than 5 accounts; estimates are suppressed above this limit.'),
(print Step = 17, Check = 'Model resource endpoints available',
    Result = iff(AccountsValid, 'Available', 'Missing or invalid account response'),
    Status = iff(AccountsValid, 'OK', 'Missing'),
    Fix = 'Check read access to every selected account; a valid endpoint is required to identify its requests.'),
(print Step = 18, Check = 'LLM calls without an identifiable deployment',
    Result = tostring(toscalar(Calls | where not(BackendMatched) | count)),
    Status = iff(toscalar(Calls | where not(BackendMatched) | count) > 0, 'Check', 'OK'),
    Fix = 'Neither the backend URL nor the LLM log named a provisioned deployment on a selected account. Select the missing accounts, or check the backend URL and LLM log deployment names. Affected deployment buckets are not allocated.'),
(print Step = 19, Check = 'Deployment buckets with incomplete APIM traffic',
    Result = tostring(toscalar(BlockedTargets | count)),
    Status = iff(toscalar(BlockedTargets | count) > 0, 'Check', 'OK'),
    Fix = 'Unmapped requests, missing gateway or LLM logs, or more than 5% of a bucket\'s calls without token usage can prevent a safe allocation.'),
(print Step = 23, Check = 'Hourly buckets where over 5% of calls lack token usage',
    Result = tostring(toscalar(TokenlessTargets | count)),
    Status = iff(toscalar(TokenlessTargets | count) > 0, 'Check', 'OK'),
    Fix = 'Those buckets are not allocated. Smaller gaps are allocated using the tokens that were logged, so tokenless calls are not part of the token share.'),
(print Step = 20, Check = 'LLM requests without matching gateway logs',
    Result = tostring(toscalar(OrphanLlm | count)),
    Status = iff(toscalar(OrphanLlm | count) > 0, 'Check', 'OK'),
    Fix = 'Check APIM gateway diagnostics and sampling. The backend and subscription cannot be identified; affected buckets are not allocated.'),
(print Step = 21, Check = 'Historical capacity and change completion',
    Result = 'Not verified',
    Status = 'Check',
    Fix = 'Confirm no deployment changes overlap the selected buckets. Current inventory does not establish historical capacity or when an update completed.'),
(print Step = 22, Check = 'APIM log rows without correlation IDs',
    Result = strcat('Gateway rows: ', tostring(toscalar(UncorrelatedGateway | count)),
        '; LLM rows: ', tostring(toscalar(UncorrelatedLlm | count))),
    Status = iff(toscalar(UncorrelatedGateway | count) + toscalar(UncorrelatedLlm | count) > 0, 'Check', 'OK'),
    Fix = 'Check APIM logging for missing correlation IDs; LLM rows can block adjacent hours as well as their own.'),
(print Step = 0, Check = 'Analysis window: whole buckets only (UTC)',
    Result = iff(AlignedEnd > AlignedStart, strcat(format_datetime(AlignedStart, 'yyyy-MM-dd HH:mm'), ' to ', format_datetime(AlignedEnd, 'yyyy-MM-dd HH:mm')), 'empty'),
    Status = iff(AlignedEnd > AlignedStart, 'OK', 'Too short'),
    Fix = 'Choose a longer time range or a finer grain: the range must contain at least one whole grain bucket.'),
(print Step = 1, Check = 'APIM gateway calls found (GatewayLogs)', Result = tostring(GatewayN),
    Status = iff(GatewayN > 0, 'OK', 'Missing'),
    Fix = 'APIM > Diagnostic settings: send GatewayLogs to this workspace (resource-specific tables).'),
(print Step = 2, Check = 'Calls that also have an LLM log (GatewayLlmLogs)', Result = strcat(LlmN, ' of ', GatewayN),
    Status = iff(LlmN > 0, iff(LlmN >= GatewayN, 'OK', 'Partial'), 'Missing'),
    Fix = 'APIM > Diagnostic settings: also send the generative AI gateway logs; on each API enable Log LLM messages.'),
(print Step = 3, Check = 'LLM calls with token usage', Result = strcat(UsageN, ' of ', LlmN),
    Status = iff(LlmN > 0 and UsageN >= LlmN, 'OK', iff(UsageN > 0, 'Partial', 'Missing')),
    Fix = 'Token counts are missing on interrupted streams and on APIs that do not return usage. Calls with no deployment, model, or tokens (for example non-model APIs) are ignored.'),
(print Step = 4, Check = 'LLM calls mapped to a backend deployment', Result = strcat(NamedN, ' of ', LlmN),
    Status = iff(LlmN > 0 and NamedN >= LlmN, 'OK', iff(NamedN > 0, 'Partial', 'Missing')),
    Fix = 'Calls are matched by the backend URL, or by the LLM log deployment or model name when the URL has none (for example Foundry agents). Check how clients address the model.'),
(print Step = 5, Check = 'PTU utilization samples in range', Result = tostring(UtilN),
    Status = iff(UtilN > 0, 'OK', 'Missing'),
    Fix = 'Check the selected model resource and access to its deployments and metrics.'),
(print Step = 6, Check = 'Deployments seen by APIM that have no utilization data', Result = tostring(NoUtilDeployments),
    Status = iff(NoUtilDeployments == 0, 'OK', 'Check'),
    Fix = 'Check the selected model resource. Pay-as-you-go deployments have no PTU.'),
(print Step = 7, Check = 'Latest utilization sample (UTC)', Result = iff(isnull(LatestUtil), 'none', format_datetime(LatestUtil, 'yyyy-MM-dd HH:mm')),
    Status = iff(isnull(LatestUtil), 'Missing', iff(LatestUtil >= AlignedEnd - 3h, 'OK', 'Stale')),
    Fix = 'Samples should reach to within 3 hours of the end of the window. Check the account metric and permissions.')
| order by Step asc
| project Check, Result, Status, ['What to do'] = iff(Status == 'OK', '', Fix)
